                    #00,                                                        ; OffsetPhase1, байтовый индекс второй фазовой пары, подготовитель добавляет 128
                    #00,                                                        ; OffsetPhase2, байтовый индекс третьей фазовой пары вычислителя смещения
                    #00,                                                        ; StateCode, байтовый код выбора обработчика ObjectStateHandlers, 60AE записывает 08
